// Modern Architectural Family Clock Card v2 (custom:modern-family-clock-card)
// 3-layer architecture: plaster wall -> digital vakgrenzen -> transparent forged iron frames + shadows.
// Hands feature exact centered eyelets & upright circular person-photo medallions halfway along each hand.

const EMBEDDED_ASSETS = {"wall_bg": "data:image/webp;base64,", "frames_transparent": "data:image/webp;base64,", "hand_iron": "data:image/webp;base64,", "hand_brass": "data:image/webp;base64,", "center_hub": "data:image/webp;base64,", "icon_thuis": "data:image/webp;base64,", "icon_werk": "data:image/webp;base64,", "icon_school": "data:image/webp;base64,", "icon_parkeren": "data:image/webp;base64,", "icon_elders": "data:image/webp;base64,", "icon_familie": "data:image/webp;base64,", "icon_onderweg": "data:image/webp;base64,"};
const HAND_PIVOTS = {"iron": 0.7438, "brass": 0.7627};

const DEFAULT_SECTIONS = [
  { name: "Thuis", key: "thuis", states: ["home", "Thuis"], zones: ["zone.home"] },
  { name: "Werk", key: "werk", states: ["Werk", "Work"], zones: ["zone.work"] },
  { name: "School", key: "school", states: ["School"], zones: ["zone.school"] },
  { name: "Familie", key: "familie", states: ["Familie", "Family"], zones: ["zone.family"] },
  { name: "Onderweg", key: "onderweg", states: ["Onderweg", "Travelling"], zones: [] },
  { name: "Elders", key: "elders", states: ["Elders", "not_home", "away"], zones: [] },
];

class ModernFamilyClockCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._config = null;
    this._hass = null;
    this._rendered = false;
  }

  static getStubConfig() {
    return {
      persons: [
        { entity: "person.alex", person_entity: "person.alex", name: "Alex", hand: "iron", color: "#1c1c1c" },
        { entity: "person.sam", person_entity: "person.sam", name: "Sam", hand: "brass", color: "#b8924a" },
      ],
    };
  }

  setConfig(config) {
    if (!config || !Array.isArray(config.persons) || config.persons.length === 0) {
      throw new Error("Configureer minimaal één persoon onder 'persons'.");
    }
    this._config = {
      asset_base_url: config.asset_base_url ?? "",
      default_section: config.default_section ?? "Elders",
      sections: config.sections && config.sections.length ? config.sections : DEFAULT_SECTIONS,
      persons: config.persons,
    };
    this._rendered = false;
    this._render();
    if (this._hass) this._update();
  }

  set hass(hass) {
    this._hass = hass;
    if (!this._rendered && this._config) this._render();
    this._update();
  }

  getCardSize() { return 7; }

  _asset(name) {
    if (this._config && this._config.asset_base_url) {
      return `${this._config.asset_base_url.replace(/\/+$/, "")}/${name}.png`;
    }
    return EMBEDDED_ASSETS[name] || "";
  }

  _raySquareDist(deg, halfSize) {
    const rad = (deg * Math.PI) / 180;
    const dx = Math.sin(rad);
    const dy = -Math.cos(rad);
    const m = Math.max(Math.abs(dx), Math.abs(dy), 1e-6);
    return { dist: halfSize / m, dx, dy };
  }

  _resolveSectionIndex(personCfg) {
    const sections = this._config.sections;
    const stateObj = this._hass?.states?.[personCfg.entity];
    const rawState = stateObj ? String(stateObj.state || "").trim() : "";
    const low = rawState.toLowerCase();
    for (let i = 0; i < sections.length; i++) {
      const sec = sections[i];
      if (sec.name && sec.name.toLowerCase() === low) return i;
      if (Array.isArray(sec.states) && sec.states.some((s) => String(s).toLowerCase() === low)) return i;
      if (Array.isArray(sec.zones)) {
        for (const z of sec.zones) {
          if (z.toLowerCase() === low) return i;
          if (z.replace(/^zone\./, "").toLowerCase() === low) return i;
          const zName = this._hass?.states?.[z]?.attributes?.friendly_name;
          if (zName && zName.toLowerCase() === low) return i;
        }
      }
    }
    const defIdx = sections.findIndex((s) => s.name.toLowerCase() === String(this._config.default_section || "").toLowerCase());
    return defIdx >= 0 ? defIdx : sections.length - 1;
  }

  _formatRelative(iso) {
    if (!iso) return "";
    const diff = Math.max(0, Math.floor((Date.now() - new Date(iso).getTime()) / 1000));
    if (diff < 60) return "zojuist";
    if (diff < 3600) return `${Math.floor(diff / 60)} min geleden`;
    if (diff < 86400) return `${Math.floor(diff / 3600)} uur geleden`;
    return `${Math.floor(diff / 86400)} d geleden`;
  }

  _openMoreInfo(entityId) {
    if (!entityId) return;
    this.dispatchEvent(new CustomEvent("hass-more-info", { bubbles: true, composed: true, detail: { entityId } }));
  }

  _render() {
    if (!this._config) return;
    const sections = this._config.sections;
    const N = sections.length;
    const step = 360 / N;

    // Exact measured frame geometry of frames_transparent.png in 0..1000 viewBox
    const cx = 501.5;
    const cy = 499.5;
    // Extend digital dividers slightly under the opaque iron frames (inner ~200, outer ~398)
    // so Layer 3 (frames_transparent) seamlessly overlaps every joint!
    const innerUnder = 194;
    const outerUnder = 404;
    const innerHalf = 201;
    const outerHalf = 398;

    let dividersSvg = "";
    for (let i = 0; i < N; i++) {
      const divDeg = (i + 0.5) * step;
      const pIn = this._raySquareDist(divDeg, innerUnder);
      const pOut = this._raySquareDist(divDeg, outerUnder);
      dividersSvg += `<line x1="${(cx + pIn.dx * pIn.dist).toFixed(1)}" y1="${(cy + pIn.dy * pIn.dist).toFixed(1)}" x2="${(cx + pOut.dx * pOut.dist).toFixed(1)}" y2="${(cy + pOut.dy * pOut.dist).toFixed(1)}" stroke="#191816" stroke-width="5.5" stroke-linecap="butt" filter="url(#ironShadow)" />`;
    }

    const crosshairSvg = `
      <line x1="${cx - innerUnder}" y1="${cy}" x2="${cx + innerUnder}" y2="${cy}" stroke="#1c1b19" stroke-width="4.5" opacity="0.88" filter="url(#ironShadow)" />
      <line x1="${cx}" y1="${cy - innerUnder}" x2="${cx}" y2="${cy + innerUnder}" stroke="#1c1b19" stroke-width="4.5" opacity="0.88" filter="url(#ironShadow)" />
    `;

    let sectorsHtml = "";
    for (let i = 0; i < N; i++) {
      const sec = sections[i];
      const deg = i * step;
      const pIn = this._raySquareDist(deg, innerHalf);
      const pOut = this._raySquareDist(deg, outerHalf);
      const r = pIn.dist + (pOut.dist - pIn.dist) * 0.51;
      const px = ((cx + pIn.dx * r) / 10).toFixed(2);
      const py = ((cy + pIn.dy * r) / 10).toFixed(2);
      const key = (sec.key || sec.name).toLowerCase();
      const iconSrc = this._asset(`icon_${key}`);
      sectorsHtml += `
        <div class="sector-node" data-sector="${i}" style="left:${px}%; top:${py}%;">
          <div class="sector-glow"></div>
          ${iconSrc ? `<img class="sector-icon" src="${iconSrc}" alt="${sec.name}" draggable="false" />` : ""}
          <span class="sector-label">${sec.name}</span>
        </div>`;
    }

    let handsHtml = "";
    this._config.persons.forEach((p, idx) => {
      const isBrass = p.hand === "brass" || idx === 1;
      const handKey = isBrass ? "hand_brass" : "hand_iron";
      const pivotPct = ((HAND_PIVOTS[isBrass ? "brass" : "iron"] || 0.75) * 100).toFixed(2);
      const handH = isBrass ? 35.5 : 41.5;
      // Place photo medallion halfway along the hand shaft (staggered slightly so two hands in the same zone never hide each other's photo)
      const medDist = isBrass ? 13.5 : 17.8;
      const ringColor = p.color || (isBrass ? "#b8924a" : "#1c1c1c");
      const cxPct = (cx / 10).toFixed(2);
      const cyPct = (cy / 10).toFixed(2);
      const medTopPct = (cy / 10 - medDist).toFixed(2);

      handsHtml += `
        <div class="hand-pivot" data-person="${idx}" style="transform-origin:${cxPct}% ${cyPct}%;">
          <img class="hand-img ${handKey}" src="${this._asset(handKey)}" alt="${p.name}" draggable="false"
               style="left:${cxPct}%; top:${cyPct}%; height:${handH}%; transform: translate(-50%, -${pivotPct}%);" />
          <div class="hand-medallion" style="left:${cxPct}%; top:${medTopPct}%; --ring:${ringColor};">
            <div class="hand-medallion-inner" data-hand-rot="${idx}">
              <img class="hand-avatar-img" data-hand-avatar="${idx}" alt="${p.name}" draggable="false" />
              <span class="hand-avatar-fb">${(p.name || "?").slice(0, 1).toUpperCase()}</span>
            </div>
          </div>
        </div>`;
    });

    let legendHtml = "";
    this._config.persons.forEach((p, idx) => {
      const isBrass = p.hand === "brass" || idx === 1;
      const dotColor = p.color || (isBrass ? "#b8924a" : "#1c1c1c");
      const targetEntity = p.person_entity || p.entity;
      legendHtml += `
        <button class="person-pill" data-person-pill="${idx}" data-entity="${targetEntity}" type="button">
          <span class="avatar-wrap" style="--ring:${dotColor};">
            <img class="avatar-img" data-avatar="${idx}" alt="${p.name}" />
            <span class="avatar-fallback">${(p.name || "?").slice(0, 1).toUpperCase()}</span>
          </span>
          <span class="person-meta">
            <span class="person-top">
              <span class="hand-swatch ${isBrass ? "brass" : "iron"}"></span>
              <span class="person-name">${p.name}</span>
            </span>
            <span class="person-loc" data-loc="${idx}">—</span>
            <span class="person-time" data-time="${idx}"></span>
          </span>
        </button>`;
    });

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        ha-card { overflow: hidden; border-radius: var(--ha-card-border-radius, 18px); background: var(--ha-card-background, var(--card-background-color, #fff)); box-shadow: var(--ha-card-box-shadow, 0 8px 28px rgba(0,0,0,.14)); padding: 0; }
        .card-wrap { display: flex; flex-direction: column; align-items: center; }
        .clock-stage { position: relative; width: 100%; max-width: 620px; aspect-ratio: 1 / 1; user-select: none; overflow: hidden; background: #ebe4d6; }
        /* Layer 1: Warm plaster wall */
        .layer-wall { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; pointer-events: none; z-index: 1; }
        /* Layer 2: Digital vakgrenzen & inner crosshair tucked under the forged frames */
        .layer-dividers { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 2; }
        /* Layer 3: Transparent wrought-iron square frames with realistic drop shadows */
        .layer-frames { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; pointer-events: none; z-index: 3; }
        /* Layer 4: Sector icons & refined labels */
        .sectors-layer { position: absolute; inset: 0; pointer-events: none; z-index: 4; }
        .sector-node { position: absolute; transform: translate(-50%, -50%); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; width: 17.5%; pointer-events: none; transition: transform .35s ease; }
        .sector-glow { position: absolute; width: 130%; height: 130%; border-radius: 50%; background: radial-gradient(circle, rgba(184,146,74,.32) 0%, rgba(184,146,74,.09) 48%, rgba(184,146,74,0) 74%); opacity: 0; transition: opacity .45s ease; pointer-events: none; }
        .sector-node.active .sector-glow { opacity: 1; }
        .sector-node.active { transform: translate(-50%, -50%) scale(1.05); }
        .sector-icon { position: relative; width: 54%; max-width: 48px; aspect-ratio: 1 / 1; object-fit: contain; filter: drop-shadow(0 1px 1px rgba(30,24,15,.14)); opacity: .88; transition: opacity .35s ease, filter .35s ease; }
        .sector-icon.icon-elders { width: 60%; max-width: 53px; }
        .sector-node.active .sector-icon { opacity: 1; filter: drop-shadow(0 2px 5px rgba(155,118,48,.34)); }
        .sector-label {
          position: relative;
          font-family: "Inter", "Avenir Next", "Montserrat", "Segoe UI", system-ui, sans-serif;
          font-size: clamp(7.5px, 1.32vw, 10.5px);
          font-weight: 600;
          letter-spacing: 0.14em;
          text-transform: uppercase;
          color: #2f2a24;
          text-shadow: 0 1px 0 rgba(255, 251, 244, 0.8);
          white-space: nowrap;
          line-height: 1;
          padding: 2px 5px;
          border-radius: 999px;
          transition: color .35s ease, background .35s ease;
        }
        .sector-node.active .sector-label {
          color: #141210;
          background: rgba(247, 241, 230, 0.72);
        }
        /* Layer 5: Animated hands + upright photo medallions */
        .hands-layer { position: absolute; inset: 0; pointer-events: none; z-index: 5; }
        .hand-pivot { position: absolute; inset: 0; transition: transform 1.15s cubic-bezier(.22, 1.12, .36, 1); will-change: transform; }
        .hand-img { position: absolute; width: auto; max-width: none; filter: drop-shadow(3px 5px 4px rgba(18,14,9,.36)); }
        .hand-medallion {
          position: absolute;
          width: 7.4%;
          aspect-ratio: 1 / 1;
          transform: translate(-50%, -50%);
          border-radius: 50%;
          border: 2.5px solid var(--ring, #1c1c1c);
          background: #f3ede2;
          box-shadow: 0 2px 6px rgba(14, 11, 7, 0.42), inset 0 0 0 1px rgba(255, 255, 255, 0.35);
          overflow: hidden;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .hand-medallion-inner {
          width: 100%;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          transition: transform 1.15s cubic-bezier(.22, 1.12, .36, 1);
          will-change: transform;
        }
        .hand-avatar-img { width: 100%; height: 100%; object-fit: cover; display: none; }
        .hand-avatar-img.loaded { display: block; }
        .hand-avatar-fb { font-family: "Inter", system-ui, sans-serif; font-weight: 700; font-size: clamp(9px, 1.7vw, 13px); color: #2b2620; }
        .hand-avatar-img.loaded + .hand-avatar-fb { display: none; }
        /* Layer 6: Center forged iron & brass hub */
        .center-hub { position: absolute; left: ${(cx / 10).toFixed(2)}%; top: ${(cy / 10).toFixed(2)}%; width: 10.6%; aspect-ratio: 1 / 1; transform: translate(-50%, -50%); object-fit: contain; pointer-events: none; filter: drop-shadow(2px 4px 5px rgba(12,10,7,.42)); z-index: 6; }
        /* Bottom legend bar */
        .legend-bar { width: 100%; box-sizing: border-box; display: grid; grid-template-columns: repeat(auto-fit, minmax(175px, 1fr)); gap: 10px; padding: 14px 16px 16px; background: var(--ha-card-background, var(--card-background-color, #fff)); border-top: 1px solid var(--divider-color, rgba(128,128,128,.16)); }
        .person-pill { appearance: none; border: 1px solid var(--divider-color, rgba(128,128,128,.22)); background: var(--secondary-background-color, rgba(128,128,128,.06)); border-radius: 14px; padding: 9px 12px; display: flex; align-items: center; gap: 11px; cursor: pointer; text-align: left; color: var(--primary-text-color, #1f1f1f); transition: transform .18s ease, border-color .2s ease; }
        .person-pill:hover { transform: translateY(-1px); border-color: #b8924a; }
        .avatar-wrap { position: relative; width: 40px; height: 40px; border-radius: 50%; flex-shrink: 0; border: 2.5px solid var(--ring, #1c1c1c); overflow: hidden; background: rgba(184,146,74,.14); display: flex; align-items: center; justify-content: center; }
        .avatar-img { width: 100%; height: 100%; object-fit: cover; display: none; }
        .avatar-img.loaded { display: block; }
        .avatar-fallback { font-weight: 700; font-size: 16px; color: var(--primary-text-color, #222); }
        .avatar-img.loaded + .avatar-fallback { display: none; }
        .person-meta { display: flex; flex-direction: column; min-width: 0; gap: 1px; }
        .person-top { display: flex; align-items: center; gap: 6px; }
        .hand-swatch { width: 14px; height: 4px; border-radius: 2px; display: inline-block; flex-shrink: 0; }
        .hand-swatch.iron { background: linear-gradient(90deg, #111, #383838); border: 1px solid rgba(255,255,255,.2); }
        .hand-swatch.brass { background: linear-gradient(90deg, #9a7432, #d8b56c); }
        .person-name { font-size: 14px; font-weight: 600; }
        .person-loc { font-size: 13px; font-weight: 600; color: #b8924a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .person-time { font-size: 11px; color: var(--secondary-text-color, #777); }
      </style>
      <ha-card>
        <div class="card-wrap">
          <div class="clock-stage">
            <img class="layer-wall" src="${this._asset("wall_bg")}" alt="" draggable="false" />
            <svg class="layer-dividers" viewBox="0 0 1000 1000" preserveAspectRatio="xMidYMid meet">
              <defs>
                <filter id="ironShadow" filterUnits="userSpaceOnUse" x="0" y="0" width="1000" height="1000">
                  <feDropShadow dx="3.2" dy="4.2" stdDeviation="3.0" flood-color="#2a2216" flood-opacity="0.32" />
                </filter>
              </defs>
              ${crosshairSvg}
              ${dividersSvg}
            </svg>
            <img class="layer-frames" src="${this._asset("frames_transparent")}" alt="Klokframe" draggable="false" />
            <div class="sectors-layer">${sectorsHtml}</div>
            <div class="hands-layer">
              ${handsHtml}
              <img class="center-hub" src="${this._asset("center_hub")}" alt="" draggable="false" />
            </div>
          </div>
          <div class="legend-bar">${legendHtml}</div>
        </div>
      </ha-card>`;

    this.shadowRoot.querySelectorAll(".person-pill").forEach((btn) => {
      btn.addEventListener("click", () => this._openMoreInfo(btn.dataset.entity));
    });
    this._rendered = true;
  }

  _update() {
    if (!this._hass || !this._config || !this._rendered) return;
    const sections = this._config.sections;
    const step = 360 / sections.length;
    const assignments = this._config.persons.map((p) => this._resolveSectionIndex(p));
    const sectorGroups = {};
    assignments.forEach((secIdx, personIdx) => {
      if (!sectorGroups[secIdx]) sectorGroups[secIdx] = [];
      sectorGroups[secIdx].push(personIdx);
    });

    this.shadowRoot.querySelectorAll(".sector-node").forEach((el) => {
      const idx = Number(el.dataset.sector);
      el.classList.toggle("active", Boolean(sectorGroups[idx] && sectorGroups[idx].length));
    });

    this._config.persons.forEach((p, idx) => {
      const secIdx = assignments[idx];
      const group = sectorGroups[secIdx] || [idx];
      const spread = group.length > 1 ? 14 : 0;
      const offset = (group.indexOf(idx) - (group.length - 1) / 2) * spread;
      const deg = secIdx * step + offset;

      const pivot = this.shadowRoot.querySelector(`.hand-pivot[data-person="${idx}"]`);
      if (pivot) pivot.style.transform = `rotate(${deg.toFixed(2)}deg)`;
      // Counter-rotate portrait inside medallion so faces stay upright!
      const rotEl = this.shadowRoot.querySelector(`[data-hand-rot="${idx}"]`);
      if (rotEl) rotEl.style.transform = `rotate(${(-deg).toFixed(2)}deg)`;

      const sec = sections[secIdx];
      const stateObj = this._hass.states?.[p.entity];
      const personObj = p.person_entity ? this._hass.states?.[p.person_entity] : null;
      const locEl = this.shadowRoot.querySelector(`[data-loc="${idx}"]`);
      if (locEl) {
        const raw = stateObj?.state;
        const extra = raw && raw.toLowerCase() !== sec.name.toLowerCase() && raw !== "home" && raw !== "not_home" && !raw.includes("Virtueel") ? ` · ${raw}` : "";
        locEl.textContent = `${sec.name}${extra}`;
      }
      const timeEl = this.shadowRoot.querySelector(`[data-time="${idx}"]`);
      if (timeEl) timeEl.textContent = this._formatRelative(stateObj?.last_changed || personObj?.last_changed);

      const pic = personObj?.attributes?.entity_picture || stateObj?.attributes?.entity_picture;
      if (pic) {
        [
          this.shadowRoot.querySelector(`[data-avatar="${idx}"]`),
          this.shadowRoot.querySelector(`[data-hand-avatar="${idx}"]`),
        ].forEach((imgEl) => {
          if (imgEl && imgEl.dataset.src !== pic) {
            imgEl.dataset.src = pic;
            imgEl.onload = () => imgEl.classList.add("loaded");
            imgEl.src = pic;
          }
        });
      }
    });
  }
}

if (!customElements.get("modern-family-clock-card")) {
  customElements.define("modern-family-clock-card", ModernFamilyClockCard);
}
window.customCards = window.customCards || [];
if (!window.customCards.some((c) => c.type === "modern-family-clock-card")) {
  window.customCards.push({
    type: "modern-family-clock-card",
    name: "Modern Family Clock",
    description: "Vierkante architectonische wandklok met eigen assets voor familie-locaties.",
  });
}
